CREATE EXTENSION postgis; CREATE TABLE businesses ( id BIGINT PRIMARY KEY, name TEXT NOT NULL, category TEXT, location GEOGRAPHY(Point, 4326), -- lng/lat geohash CHAR(8), -- denormalized for fast cell lookups rating REAL, hours JSONB, updated_at TIMESTAMP
); CREATE INDEX idx_biz_location ON businesses USING GIST (location);
CREATE INDEX idx_biz_geohash ON businesses (geohash, category);
